def prepare_emails(apps, schema_editor):
    """Make every email usable as a unique login before the username is dropped.

    Addresses are lowercased. Accounts without an email get a placeholder under
    the reserved .invalid domain, derived from their username, so an admin can
    spot and correct them.
    """
    User = apps.get_model('accounts', 'CustomUser')
    seen = {}
    for user in User.objects.order_by('pk'):
        email = (user.email or '').strip().lower()
        if not email:
            email = f'{user.username.lower()}@change-me.invalid'
            print(f'\n  User "{user.username}" had no email; set to {email}', end='')
        if email in seen:
            raise RuntimeError(
                f'Users "{seen[email]}" and "{user.username}" share the email {email}. '
                'Give one of them a different email address, then run migrate again.'
            )
        seen[email] = user.username
        if email != user.email:
            user.email = email
            user.save(update_fields=['email'])


